private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index > 0) {
        char c = headerPart.charAt(index - 1);
        if (c == '\n') {
            if (index > 1 && headerPart.charAt(index - 2) == '\r') {
                return index - 2;
            } else {
                return index - 1;
            }
        }
        index--;
    }
    return -1;
}

