public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings currentMappings = getCurrentMappings(tableName);
    Mappings diff = new Mappings();

    if (currentMappings == null || mappings == null) {
        return diff;
    }

    Map<String, Field> currentFields = currentMappings.getFields();
    Map<String, Field> inputFields = mappings.getFields();

    if (currentFields == null || inputFields == null) {
        return diff;
    }

    for (Map.Entry<String, Field> entry : inputFields.entrySet()) {
        String fieldName = entry.getKey();
        Field field = entry.getValue();

        if (!currentFields.containsKey(fieldName)) {
            diff.addField(fieldName, field);
        }
    }

    return diff;
}

