static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract year, month, day from the timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Create a date object
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.clear();
    cal.set(year, month - 1, day);

    // Get the day of the week (1 = Sunday, 2 = Monday, ..., 7 = Saturday)
    int dayOfWeek = cal.get(java.util.Calendar.DAY_OF_WEEK);

    // Calculate the offset to the start of the period
    // We want to find the most recent date that is a multiple of dayStep from some reference
    // The reference is the first day of the month (or we can use a fixed reference)
    // Let's use the first day of the month as reference
    cal.set(java.util.Calendar.DAY_OF_MONTH, 1);
    long firstDayOfMonth = cal.getTimeInMillis();

    // Get the current date in millis
    cal.set(year, month - 1, day);
    long currentDate = cal.getTimeInMillis();

    // Calculate the number of days since the first day of the month
    long daysSinceFirst = (currentDate - firstDayOfMonth) / (1000 * 60 * 60 * 24);

    // Calculate the bucket start day
    long bucketStartDay = (daysSinceFirst / dayStep) * dayStep;

    // Set the calendar to the bucket start day
    cal.setTimeInMillis(firstDayOfMonth + bucketStartDay * 1000 * 60 * 60 * 24);

    // Format back to long
    int newYear = cal.get(java.util.Calendar.YEAR);
    int newMonth = cal.get(java.util.Calendar.MONTH) + 1;
    int newDay = cal.get(java.util.Calendar.DAY_OF_MONTH);

    return newYear * 10000L + newMonth * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size += 1;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            size += 3;
        } else {
            // Surrogate pair
            size += 4;
            i++; // Skip the low surrogate
        }
    }
    return size;
}

