public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    final int len = str.length();
    if (len == 0) {
        return lb;
    }
    // Estimate the number of bytes needed (worst case: each char is 3 bytes in UTF-8)
    int estimatedBytes = len * 3;
    byte[] buffer = new byte[estimatedBytes];
    int offset = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            buffer[offset++] = (byte) (0xC0 | (c >> 6));
            buffer[offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (c < 0xD800 || c > 0xDFFF) {
            buffer[offset++] = (byte) (0xE0 | (c >> 12));
            buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer[offset++] = (byte) (0x80 | (c & 0x3F));
        } else {
            // Surrogate pair
            if (i + 1 < len) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    int codePoint = 0x10000 + ((c - 0xD800) << 10) + (low - 0xDC00);
                    buffer[offset++] = (byte) (0xF0 | (codePoint >> 18));
                    buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
                    buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
                    buffer[offset++] = (byte) (0x80 | (codePoint & 0x3F));
                    i++;
                } else {
                    // Invalid surrogate, write replacement character
                    buffer[offset++] = (byte) 0xEF;
                    buffer[offset++] = (byte) 0xBF;
                    buffer[offset++] = (byte) 0xBD;
                }
            } else {
                // Unpaired surrogate, write replacement character
                buffer[offset++] = (byte) 0xEF;
                buffer[offset++] = (byte) 0xBF;
                buffer[offset++] = (byte) 0xBD;
            }
        }
    }
    // If the buffer was over-allocated, copy to a smaller array
    if (offset < buffer.length) {
        byte[] trimmed = new byte[offset];
        System.arraycopy(buffer, 0, trimmed, 0, offset);
        buffer = trimmed;
    }
    session.writeBytes(buffer, 0, offset);
    return lb;
}

