public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution
    // Assuming the format is ${var} where var is a key in props
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        if (i < value.length() - 2 && value.charAt(i) == '$' && value.charAt(i + 1) == '{') {
            int end = value.indexOf('}', i + 2);
            if (end != -1) {
                String varName = value.substring(i + 2, end);
                String varValue = props.getProperty(varName);
                if (varValue != null) {
                    result.append(varValue);
                } else {
                    result.append(value.substring(i, end + 1));
                }
                i = end + 1;
            } else {
                result.append(value.charAt(i));
                i++;
            }
        } else {
            result.append(value.charAt(i));
            i++;
        }
    }
    return result.toString();
}

