protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    // Create a list of edges from the set
    List<E> edgeList = new ArrayList<>(tour);

    // If the tour is empty, return an empty path
    if (edgeList.isEmpty()) {
        return new GraphPath<>(graph, null, null, 0, new ArrayList<>());
    }

    // Start with the first edge
    E firstEdge = edgeList.get(0);
    V startVertex = graph.getEdgeSource(firstEdge);
    V endVertex = graph.getEdgeTarget(firstEdge);

    // Build the path by traversing edges
    List<V> vertexList = new ArrayList<>();
    List<E> pathEdgeList = new ArrayList<>();

    vertexList.add(startVertex);
    pathEdgeList.add(firstEdge);

    // Remove the first edge from the set
    Set<E> remainingEdges = new HashSet<>(tour);
    remainingEdges.remove(firstEdge);

    V currentVertex = endVertex;

    // Continue building the path until all edges are used
    while (!remainingEdges.isEmpty()) {
        // Find an edge that starts from the current vertex
        E nextEdge = null;
        for (E edge : remainingEdges) {
            if (graph.getEdgeSource(edge).equals(currentVertex)) {
                nextEdge = edge;
                break;
            }
        }

        // If no edge found starting from current vertex, try edges ending at current vertex
        if (nextEdge == null) {
            for (E edge : remainingEdges) {
                if (graph.getEdgeTarget(edge).equals(currentVertex)) {
                    nextEdge = edge;
                    break;
                }
            }
        }

        // If no edge found, break (should not happen in a valid tour)
        if (nextEdge == null) {
            break;
        }

        // Add the edge to the path
        pathEdgeList.add(nextEdge);
        remainingEdges.remove(nextEdge);

        // Update the current vertex
        if (graph.getEdgeSource(nextEdge).equals(currentVertex)) {
            currentVertex = graph.getEdgeTarget(nextEdge);
        } else {
            currentVertex = graph.getEdgeSource(nextEdge);
        }

        vertexList.add(currentVertex);
    }

    // Calculate the total weight
    double totalWeight = 0;
    for (E edge : pathEdgeList) {
        totalWeight += graph.getEdgeWeight(edge);
    }

    // Return the graph path
    return new GraphPath<>(graph, startVertex, currentVertex, totalWeight, pathEdgeList);
}

