private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == this) {
        return;
    }
    ListNode<E> node = list.head;
    while (node != null) {
        ListNode<E> next = node.next;
        // Remove from list
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            list.head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            list.tail = node.prev;
        }
        node.prev = null;
        node.next = null;
        // Add to this list
        if (head == null) {
            head = node;
            tail = node;
        } else {
            tail.next = node;
            node.prev = tail;
            tail = node;
        }
        node = next;
    }
    list.head = null;
    list.tail = null;
}

